const required = ['EVOLUTION_API_URL', 'EVOLUTION_INSTANCE', 'EVOLUTION_API_KEY', 'QA_WHATSAPP_NUMBER'];
const missing = required.filter((k) => !$env[k] || String($env[k]).trim() === '');
if (missing.length) {
  throw new Error(
    'Configuracao ausente no container n8n (nao basta na API): ' +
      missing.join(', ') +
      '. Preencha no .env da raiz e recrie o servico n8n (docker compose ... up -d --force-recreate n8n).'
  );
}
const number = String($env.QA_WHATSAPP_NUMBER).replace(/\D/g, '');
if (!/^55\d{10,11}$/.test(number)) {
  throw new Error('QA_WHATSAPP_NUMBER invalido no container n8n — use formato 55DDDNUMERO');
}
return [{ json: { number, instance: $env.EVOLUTION_INSTANCE, baseUrl: $env.EVOLUTION_API_URL } }];

const res = $input.first().json;
const status = res.statusCode ?? res.status ?? 0;
if (status >= 200 && status < 300) {
  return [{ json: { ok: true, status, message: 'Envio Evolution OK (verificar WhatsApp QA)' } }];
}
return [{ json: { ok: false, status, error: res.error || res.message || 'Falha Evolution', body: res } }];
